#!/bin/sh
# Compiles GNM renderer shaders (ref/gl/ps4/shaders) into
# ref/gl/ps4/gnm_shaders.c: GLSL -> SPIR-V (glslang) -> PS4 shader
# binary (opengnm-psbc with our patch, see scripts/ps4/psbc/build.sh).
# Only needed after changing shaders, generated file is kept in the repository.
#
# Usage: scripts/ps4/gnm/compile-shaders.sh
#   GLSLANG - glslang standalone binary (default: glslang from PATH)
#   PSBC    - patched opengnm-psbc binary (default: opengnm-psbc from PATH)
set -e

ROOT=$(cd "$(dirname "$0")/../../.." && pwd)
SRC="$ROOT/ref/gl/ps4/shaders"
OUT="$ROOT/ref/gl/ps4/gnm_shaders.c"
GLSLANG=${GLSLANG:-glslang}
PSBC=${PSBC:-opengnm-psbc}
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

# compile <source> <stage> <name> [defines...]
compile()
{
	src="$1"; stage="$2"; name="$3"; shift 3
	case "$stage" in
	vert) psbc_stage=vertex ;;
	frag) psbc_stage=fragment ;;
	esac
	"$GLSLANG" -V -S "$stage" "$@" "$SRC/$src" -o "$TMP/$name.spv" > "$TMP/glslang.log" || {
		cat "$TMP/glslang.log" >&2
		exit 1
	}
	# -4: PS4 base GPU (GFX7), also runs on PS4 Pro
	"$PSBC" -s "$psbc_stage" -f "$TMP/$name.spv" -o "$TMP/$name.sb" -4 > "$TMP/psbc.log" 2>&1 || {
		cat "$TMP/psbc.log" >&2
		exit 1
	}
	python3 - "$TMP/$name.sb" "$name" >> "$TMP/arrays.c" <<'PYEOF'
import sys
data = open(sys.argv[1], 'rb').read()
print('static const uint8_t %s[%d] __attribute__((aligned(16))) =\n{' % (sys.argv[2], len(data)))
for i in range(0, len(data), 16):
	print('\t' + ', '.join('0x%02x' % b for b in data[i:i + 16]) + ',')
print('};\n')
PYEOF
	echo "  $name"
}

: > "$TMP/arrays.c"

compile clear.vert.glsl vert clear_vs
compile clear.frag.glsl frag clear_ps

# vertex shaders: attribute mask, bit 0 - color, 1 - texcoord0, 2 - texcoord1
v=0
while [ $v -lt 8 ]; do
	compile gl2.vert.glsl vert gl2_vs_$v \
		-DATTR_COLOR=$(( v & 1 )) -DATTR_TEXCOORD0=$(( (v >> 1) & 1 )) -DATTR_TEXCOORD1=$(( (v >> 2) & 1 ))
	v=$(( v + 1 ))
done

# fragment shaders: attribute mask as above, bit 3 - alpha test, bit 4 - fog
f=0
while [ $f -lt 32 ]; do
	compile gl2.frag.glsl frag gl2_ps_$f \
		-DATTR_COLOR=$(( f & 1 )) -DATTR_TEXCOORD0=$(( (f >> 1) & 1 )) -DATTR_TEXCOORD1=$(( (f >> 2) & 1 )) \
		-DFEAT_ALPHA_TEST=$(( (f >> 3) & 1 )) -DFEAT_FOG=$(( (f >> 4) & 1 ))
	f=$(( f + 1 ))
done

{
	echo '// Generated by scripts/ps4/gnm/compile-shaders.sh from ref/gl/ps4/shaders, do not edit'
	echo '#include <stdint.h>'
	echo '#include "gnm_shaders.h"'
	echo
	cat "$TMP/arrays.c"
	echo 'const gnm_shader_blob_t gnm_shader_clear_vs = { clear_vs, sizeof( clear_vs ) };'
	echo 'const gnm_shader_blob_t gnm_shader_clear_ps = { clear_ps, sizeof( clear_ps ) };'
	echo
	echo 'const gnm_shader_blob_t gnm_shader_gl2_vs[GNM_GL2_VS_COUNT] ='
	echo '{'
	v=0
	while [ $v -lt 8 ]; do echo "	{ gl2_vs_$v, sizeof( gl2_vs_$v ) },"; v=$(( v + 1 )); done
	echo '};'
	echo
	echo 'const gnm_shader_blob_t gnm_shader_gl2_ps[GNM_GL2_PS_COUNT] ='
	echo '{'
	f=0
	while [ $f -lt 32 ]; do echo "	{ gl2_ps_$f, sizeof( gl2_ps_$f ) },"; f=$(( f + 1 )); done
	echo '};'
} > "$OUT"

echo "Done: $OUT"
